-- Prepaid custody: governed terms, opaque funding intents and immutable lots.
CREATE TABLE nc_prepaid_accounts(subscription_id TEXT PRIMARY KEY REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE nc_prepaid_requests(id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),kind TEXT NOT NULL CHECK(kind IN ('grant','consent')),payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),base_revision INTEGER NOT NULL,prepared_by_id TEXT NOT NULL REFERENCES nc_members(id),prepared_by TEXT NOT NULL,prepared_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),decided_by_id TEXT,decided_by TEXT,decided_at INTEGER,approval_mode TEXT);
CREATE TABLE nc_prepaid_consents(id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),request_id TEXT NOT NULL UNIQUE REFERENCES nc_prepaid_requests(id),terms_json TEXT NOT NULL CHECK(json_valid(terms_json)),threshold_n INTEGER NOT NULL CHECK(threshold_n>=0),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')),approved_at INTEGER NOT NULL,revoked_at INTEGER);
CREATE UNIQUE INDEX nc_prepaid_one_consent ON nc_prepaid_consents(subscription_id) WHERE status='active';
CREATE TABLE nc_prepaid_funding_intents(id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),request_id TEXT REFERENCES nc_prepaid_requests(id),consent_id TEXT REFERENCES nc_prepaid_consents(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),terms_json TEXT NOT NULL CHECK(json_valid(terms_json)),invoice_id TEXT UNIQUE REFERENCES nc_invoices(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','funded','cancelled')),created_at INTEGER NOT NULL,funded_at INTEGER,payment_id TEXT REFERENCES nc_payments(id),provider_ref TEXT);
CREATE UNIQUE INDEX nc_prepaid_one_pending_topup ON nc_prepaid_funding_intents(consent_id) WHERE status='pending' AND consent_id IS NOT NULL;
CREATE TABLE nc_prepaid_grants(id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),request_id TEXT REFERENCES nc_prepaid_requests(id),funding_id TEXT UNIQUE REFERENCES nc_prepaid_funding_intents(id),kind TEXT NOT NULL CHECK(kind IN ('money','units')),source TEXT NOT NULL CHECK(source IN ('purchase','promotion')),amount_n INTEGER NOT NULL CHECK(typeof(amount_n)='integer' AND amount_n>0),value_cents INTEGER NOT NULL CHECK(value_cents>=0),meter_id TEXT REFERENCES nc_meters(id),effective_date TEXT NOT NULL,expires_date TEXT,priority INTEGER NOT NULL,rollover_months INTEGER NOT NULL,rollover_percent INTEGER NOT NULL,rollover_cap_n INTEGER,expiry_consent INTEGER NOT NULL CHECK(expiry_consent=1),purchase_invoice_id TEXT REFERENCES nc_invoices(id),purchase_line_id TEXT REFERENCES nc_invoice_lines(id),created_at INTEGER NOT NULL,CHECK((source='promotion' AND value_cents=0 AND funding_id IS NULL) OR (source='purchase' AND value_cents>0 AND funding_id IS NOT NULL AND purchase_invoice_id IS NOT NULL AND purchase_line_id IS NOT NULL)));
CREATE TABLE nc_prepaid_ledger(id TEXT PRIMARY KEY,grant_id TEXT NOT NULL REFERENCES nc_prepaid_grants(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),kind TEXT NOT NULL CHECK(kind IN ('grant','drawdown','expiry','rollover','correction','refund')),amount_n INTEGER NOT NULL CHECK(typeof(amount_n)='integer'),liability_cents INTEGER NOT NULL CHECK(typeof(liability_cents)='integer'),recognition_cents INTEGER NOT NULL CHECK(typeof(recognition_cents)='integer'),service_date TEXT NOT NULL,invoice_id TEXT REFERENCES nc_invoices(id),line_index INTEGER,purchase_invoice_id TEXT REFERENCES nc_invoices(id),purchase_line_id TEXT REFERENCES nc_invoice_lines(id),created_at INTEGER NOT NULL);
CREATE INDEX nc_prepaid_ledger_account ON nc_prepaid_ledger(subscription_id,service_date,id);
CREATE UNIQUE INDEX nc_prepaid_boundary_once ON nc_prepaid_ledger(grant_id,service_date,kind) WHERE kind IN ('expiry','rollover');
CREATE TRIGGER nc_prepaid_ledger_balance BEFORE INSERT ON nc_prepaid_ledger WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND (NEW.kind<>'correction' AND COALESCE((SELECT SUM(amount_n) FROM nc_prepaid_ledger WHERE grant_id=NEW.grant_id),0)+NEW.amount_n<0 OR NOT EXISTS(SELECT 1 FROM nc_prepaid_grants g WHERE g.id=NEW.grant_id AND g.customer_id=NEW.customer_id AND g.subscription_id=NEW.subscription_id)) BEGIN SELECT RAISE(ABORT,'nectar_guard_prepaid_balance_changed'); END;
CREATE TRIGGER nc_prepaid_ledger_source BEFORE INSERT ON nc_prepaid_ledger WHEN NEW.kind='drawdown' AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_invoices WHERE id=NEW.invoice_id AND status='issued' AND customer_id=NEW.customer_id AND subscription_id=NEW.subscription_id) BEGIN SELECT RAISE(ABORT,'nectar_guard_prepaid_source_changed'); END;
CREATE TRIGGER nc_prepaid_grant_funding BEFORE INSERT ON nc_prepaid_grants WHEN NEW.source='purchase' AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_prepaid_funding_intents f JOIN nc_invoice_lines l ON l.id=NEW.purchase_line_id WHERE f.id=NEW.funding_id AND f.status='funded' AND f.customer_id=NEW.customer_id AND f.subscription_id=NEW.subscription_id AND f.invoice_id=NEW.purchase_invoice_id AND l.invoice_id=f.invoice_id AND l.kind='prepaid_purchase' AND l.amount_cents=NEW.value_cents) BEGIN SELECT RAISE(ABORT,'nectar_guard_prepaid_funding_required'); END;
