-- CAT-010: signed customer acceptance, independently approved exact terms and
-- immutable balance-crossing claims. Cap includes all reserved exposure.
CREATE TABLE nc_prepaid_topup_authorizations(
 id TEXT PRIMARY KEY,consent_id TEXT NOT NULL REFERENCES nc_prepaid_consents(id),subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),
 quote_json TEXT NOT NULL CHECK(json_valid(quote_json)),basis_hash TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,
 prepared_by_id TEXT NOT NULL REFERENCES nc_members(id),prepared_at INTEGER NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('awaiting_customer','pending','active','rejected','revoked','card_changed','expired')),
 customer_session_id TEXT,accepted_at INTEGER,accepted_basis_hash TEXT,approved_by_id TEXT REFERENCES nc_members(id),approved_at INTEGER,approval_mode TEXT,ended_at INTEGER,
 CHECK(status NOT IN ('pending','active','rejected') OR (customer_session_id IS NOT NULL AND accepted_at IS NOT NULL AND accepted_basis_hash=basis_hash)),
 CHECK(status<>'active' OR (approved_by_id IS NOT NULL AND approved_at IS NOT NULL AND approval_mode IN ('single-approver','two-person'))));
CREATE UNIQUE INDEX nc_prepaid_topup_active ON nc_prepaid_topup_authorizations(subscription_id) WHERE status='active';
CREATE TABLE nc_prepaid_topup_states(authorization_id TEXT PRIMARY KEY REFERENCES nc_prepaid_topup_authorizations(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),armed INTEGER NOT NULL CHECK(armed IN (0,1)),cycle INTEGER NOT NULL CHECK(cycle>=0),revision INTEGER NOT NULL CHECK(revision>=0));
CREATE TABLE nc_prepaid_topup_claims(
 id TEXT PRIMARY KEY,authorization_id TEXT NOT NULL REFERENCES nc_prepaid_topup_authorizations(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),subscription_id TEXT NOT NULL REFERENCES nc_subscriptions(id),
 cycle INTEGER NOT NULL,period TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(typeof(amount_cents)='integer' AND amount_cents BETWEEN 50 AND 99999999),balance_n INTEGER NOT NULL CHECK(balance_n>=0),funding_id TEXT NOT NULL UNIQUE REFERENCES nc_prepaid_funding_intents(id),intent_key TEXT NOT NULL UNIQUE,
 status TEXT NOT NULL CHECK(status IN ('reserved','issued','claimed','uncertain','collected','declined','customer_action_required','stopped')),claimed_at INTEGER NOT NULL,revision TEXT NOT NULL,
 invoice_id TEXT UNIQUE REFERENCES nc_invoices(id),payment_intent_ref TEXT UNIQUE,charge_ref TEXT UNIQUE,proof_json TEXT CHECK(proof_json IS NULL OR json_valid(proof_json)),payment_id TEXT UNIQUE REFERENCES nc_payments(id),allocation_id TEXT UNIQUE REFERENCES nc_allocations(id),error_code TEXT,observed_at INTEGER,
 UNIQUE(authorization_id,cycle),CHECK(status<>'collected' OR (invoice_id IS NOT NULL AND payment_intent_ref IS NOT NULL AND charge_ref IS NOT NULL AND proof_json IS NOT NULL AND payment_id IS NOT NULL AND allocation_id IS NOT NULL)));
CREATE TRIGGER nc_prepaid_topup_authorization_insert BEFORE INSERT ON nc_prepaid_topup_authorizations WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND (NEW.status<>'awaiting_customer' OR NEW.accepted_at IS NOT NULL OR NEW.approved_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM nc_prepaid_consents p JOIN nc_members m ON m.id=NEW.prepared_by_id WHERE p.id=NEW.consent_id AND p.customer_id=NEW.customer_id AND p.subscription_id=NEW.subscription_id AND p.status='active' AND m.role='owner' AND m.status='active')) BEGIN SELECT RAISE(ABORT,'nectar_guard_topup_authorization_source_changed'); END;
CREATE TRIGGER nc_prepaid_topup_authorization_update BEFORE UPDATE ON nc_prepaid_topup_authorizations WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND (
 OLD.id IS NOT NEW.id OR OLD.consent_id IS NOT NEW.consent_id OR OLD.subscription_id IS NOT NEW.subscription_id OR OLD.customer_id IS NOT NEW.customer_id OR OLD.quote_json IS NOT NEW.quote_json OR OLD.basis_hash IS NOT NEW.basis_hash OR OLD.start_date IS NOT NEW.start_date OR OLD.end_date IS NOT NEW.end_date OR OLD.prepared_by_id IS NOT NEW.prepared_by_id OR OLD.prepared_at IS NOT NEW.prepared_at
 OR OLD.status IN ('rejected','revoked','card_changed','expired')
 OR (OLD.accepted_at IS NOT NULL AND (OLD.accepted_at IS NOT NEW.accepted_at OR OLD.customer_session_id IS NOT NEW.customer_session_id OR OLD.accepted_basis_hash IS NOT NEW.accepted_basis_hash))
 OR (OLD.approved_at IS NOT NULL AND (OLD.approved_at IS NOT NEW.approved_at OR OLD.approved_by_id IS NOT NEW.approved_by_id OR OLD.approval_mode IS NOT NEW.approval_mode))
 OR NOT((OLD.status='awaiting_customer' AND NEW.status IN ('pending','revoked')) OR (OLD.status='pending' AND NEW.status IN ('active','rejected','revoked')) OR (OLD.status='active' AND NEW.status IN ('revoked','card_changed','expired')))
 OR (NEW.status='pending' AND NOT EXISTS(SELECT 1 FROM nc_portal_sessions s WHERE s.id=NEW.customer_session_id AND s.customer_id=NEW.customer_id AND s.revoked_at IS NULL AND s.issued_at<=NEW.accepted_at AND s.expires_at>NEW.accepted_at))
 OR (NEW.status='active' AND (NOT EXISTS(SELECT 1 FROM nc_members m WHERE m.id=NEW.approved_by_id AND m.status='active' AND m.role IN ('owner','finance')) OR (NEW.prepared_by_id=NEW.approved_by_id AND (NEW.approval_mode<>'single-approver' OR EXISTS(SELECT 1 FROM nc_members WHERE id<>NEW.prepared_by_id AND status='active' AND role IN ('owner','finance'))))))
) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_prepaid_topup_claim_insert BEFORE INSERT ON nc_prepaid_topup_claims WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND (NEW.status<>'reserved' OR NOT EXISTS(SELECT 1 FROM nc_prepaid_topup_authorizations a JOIN nc_prepaid_funding_intents f ON f.id=NEW.funding_id WHERE a.id=NEW.authorization_id AND a.status='active' AND a.customer_id=NEW.customer_id AND a.subscription_id=NEW.subscription_id AND f.customer_id=NEW.customer_id AND f.subscription_id=NEW.subscription_id AND f.amount_cents=NEW.amount_cents AND f.status='pending' AND NEW.amount_cents=json_extract(a.quote_json,'$.amountCents') AND NEW.balance_n<=json_extract(a.quote_json,'$.thresholdN') AND COALESCE((SELECT SUM(amount_cents) FROM nc_prepaid_topup_claims WHERE authorization_id=a.id AND period=NEW.period),0)+NEW.amount_cents<=json_extract(a.quote_json,'$.periodCapCents'))) BEGIN SELECT RAISE(ABORT,'nectar_guard_topup_claim_changed'); END;
CREATE TRIGGER nc_prepaid_topup_claim_update BEFORE UPDATE ON nc_prepaid_topup_claims WHEN NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND (
 OLD.id IS NOT NEW.id OR OLD.authorization_id IS NOT NEW.authorization_id OR OLD.customer_id IS NOT NEW.customer_id OR OLD.subscription_id IS NOT NEW.subscription_id OR OLD.cycle IS NOT NEW.cycle OR OLD.period IS NOT NEW.period OR OLD.amount_cents IS NOT NEW.amount_cents OR OLD.balance_n IS NOT NEW.balance_n OR OLD.funding_id IS NOT NEW.funding_id OR OLD.intent_key IS NOT NEW.intent_key OR OLD.claimed_at IS NOT NEW.claimed_at
 OR OLD.status IN ('collected','declined','customer_action_required','stopped') OR (OLD.invoice_id IS NOT NULL AND OLD.invoice_id IS NOT NEW.invoice_id) OR (OLD.payment_intent_ref IS NOT NULL AND OLD.payment_intent_ref IS NOT NEW.payment_intent_ref) OR (OLD.charge_ref IS NOT NULL AND OLD.charge_ref IS NOT NEW.charge_ref)
 OR NOT((OLD.status='reserved' AND NEW.status IN ('issued','stopped')) OR (OLD.status='issued' AND NEW.status IN ('claimed','stopped')) OR (OLD.status IN ('claimed','uncertain') AND NEW.status IN ('uncertain','collected','declined','customer_action_required','stopped')))
 OR (NEW.status='collected' AND NOT EXISTS(SELECT 1 FROM nc_payments p JOIN nc_allocations a ON a.payment_id=p.id WHERE p.id=NEW.payment_id AND a.id=NEW.allocation_id AND a.invoice_id=NEW.invoice_id AND p.customer_id=NEW.customer_id AND p.amount_cents=NEW.amount_cents AND a.amount_cents=NEW.amount_cents AND p.method='card_external'))
) BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;

