 BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TRIGGER nc_invoice_automation_request_keep BEFORE DELETE ON nc_invoice_automation_requests
 BEGIN SELECT RAISE(ABORT,'nectar_immutable'); END;
CREATE TABLE nc_invoice_automation_runs (
 id TEXT PRIMARY KEY, business_day TEXT NOT NULL UNIQUE, policy_revision INTEGER NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('running','completed','failed')), result_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL
);

CREATE TRIGGER nc_guard_invoice_automation BEFORE INSERT ON nc_guard WHEN NEW.ok IS NOT 1 AND NEW.code='invoice_automation_changed'
 BEGIN SELECT RAISE(ABORT,'nectar_guard_invoice_automation_changed'); END;

-- Historical provider observations. No mandate or authorization is represented.
-- String columns permit privacy redaction by the generic erasure inventory.
CREATE TABLE nc_customer_payment_method_snapshots (
  id TEXT PRIMARY KEY,
  customer_id TEXT NOT NULL REFERENCES nc_customers(id),
  binding_id TEXT NOT NULL REFERENCES nc_stripe_customer_bindings(id),
  binding_revision TEXT NOT NULL,
  account_ref TEXT NOT NULL,
  stripe_customer_ref TEXT NOT NULL,
  fetched_at INTEGER NOT NULL,
  UNIQUE(customer_id,binding_id)
);
CREATE TABLE nc_customer_payment_methods (
  id TEXT PRIMARY KEY,
  customer_id TEXT NOT NULL REFERENCES nc_customers(id),
  snapshot_id TEXT NOT NULL REFERENCES nc_customer_payment_method_snapshots(id),
  payment_method_ref TEXT NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN ('card','us_bank_account')),
  brand TEXT,
  last4 TEXT NOT NULL,
  exp_month INTEGER,
  exp_year INTEGER,
  bank_name TEXT,
  account_type TEXT,
  UNIQUE(snapshot_id,payment_method_ref)
